 12→export function printSummary(
 13→  scenarioName: string,
 14→  metrics: OperationMetrics[],
 15→  totalDurationMs: number,
 16→  clientCount: number
 17→): void {
 18→  const totalOps = metrics.reduce((sum, m) => sum + m.count, 0);
 19→  const totalErrors = metrics.reduce((sum, m) => sum + m.errors, 0);
 20→  const totalBytes = metrics.reduce((sum, m) => sum + (m.bytesTransferred ?? 0), 0);
 21→
 22→  console.log(`\n${'='.repeat(80)}`);
 23→  console.log(`LOAD TEST: ${scenarioName}`);
 24→  console.log(`${'='.repeat(80)}`);
 25→  console.log(`Clients:     ${clientCount}`);
 26→  console.log(`Duration:    ${(totalDurationMs / 1000).toFixed(1)}s`);
 27→  console.log(`Total ops:   ${totalOps} (${totalErrors} errors)`);
 28→  const durationSec = Math.max(totalDurationMs, 1) / 1000;
 29→  console.log(`Throughput:  ${(totalOps / durationSec).toFixed(2)} ops/sec`);
 30→  if (totalBytes > 0) {
 31→    console.log(`Data:        ${formatBytes(totalBytes)}`);
 32→  }
 33→  console.log(`${'─'.repeat(80)}`);
 34→
 35→  // Table header
 36→  console.log(
 37→    padRight('Operation', 22) +
 38→      padRight('Count', 8) +
 39→      padRight('Errors', 8) +
 40→      padRight('p50', 10) +
 41→      padRight('p95', 10) +
 42→      padRight('p99', 10) +
 43→      padRight('Max', 10)
 44→  );
 45→  console.log('─'.repeat(80));
 46→
 47→  for (const m of metrics) {
 48→    console.log(
 49→      padRight(m.operation, 22) +
 50→        padRight(String(m.count), 8) +
 51→        padRight(String(m.errors), 8) +
 52→        padRight(fmtMs(m.latency.p50), 10) +
 53→        padRight(fmtMs(m.latency.p95), 10) +
 54→        padRight(fmtMs(m.latency.p99), 10) +
 55→        padRight(fmtMs(m.latency.max), 10)
 56→    );
 57→  }
 58→
 59→  console.log(`${'='.repeat(80)}\n`);
 60→}
