14→export function markEnd(operation: string, startMark: string): PerformanceMeasure | null {
15→  if (!PERF_ENABLED || !startMark) return null;
16→  const endMark = `cipherbox:${operation}:end`;
17→  performance.mark(endMark);
18→  const measure = performance.measure(`cipherbox:${operation}`, startMark, endMark);
19→  performance.clearMarks(startMark);
20→  performance.clearMarks(endMark);
21→  return measure;
22→}
23→
24→export async function withPerf<T>(operation: string, fn: () => Promise<T>): Promise<T> {
25→  const start = markStart(operation);
26→  try {
27→    return await fn();
28→  } finally {
29→    markEnd(operation, start);
30→  }
31→}
