1049→@@ -0,0 +1,31 @@
1050→+const PERF_ENABLED =
1051→+  typeof performance !== 'undefined' &&
1052→+  typeof performance.mark === 'function' &&
1053→+  ((typeof globalThis !== 'undefined' && (globalThis as any).__CIPHERBOX_PERF__) ||
1054→+    (typeof process !== 'undefined' && process.env.NODE_ENV !== 'production'));
1055→+
1056→+export function markStart(operation: string): string {
1057→+  if (!PERF_ENABLED) return '';
1058→+  const markName = `cipherbox:${operation}:start`;
1059→+  performance.mark(markName);
1060→+  return markName;
1061→+}
1062→+
1063→+export function markEnd(operation: string, startMark: string): PerformanceMeasure | null {
1064→+  if (!PERF_ENABLED || !startMark) return null;
1065→+  const endMark = `cipherbox:${operation}:end`;
1066→+  performance.mark(endMark);
1067→+  const measure = performance.measure(`cipherbox:${operation}`, startMark, endMark);
1068→+  performance.clearMarks(startMark);
1069→+  performance.clearMarks(endMark);
1070→+  return measure;
1071→+}
1072→+
1073→+export async function withPerf<T>(operation: string, fn: () => Promise<T>): Promise<T> {
1074→+  const start = markStart(operation);
1075→+  try {
1076→+    return await fn();
1077→+  } finally {
1078→+    markEnd(operation, start);
1079→+  }
1080→+}
