1334→@@ -0,0 +1,57 @@
1335→+/**
1336→+ * Load Test Threshold Checking
1337→+ *
1338→+ * Defines pass/fail thresholds for load test scenarios.
1339→+ * Compares observed metrics against defined limits and produces
1340→+ * actionable violation messages for CI output.
1341→+ */
1342→+
1343→+import type { OperationMetrics } from './metrics';
1344→+
1345→+export interface ThresholdConfig {
1346→+  /** Operation name to match against OperationMetrics.operation */
1347→+  operation: string;
1348→+  /** Maximum allowed p95 latency in milliseconds */
1349→+  p95MaxMs: number;
1350→+  /** Maximum allowed error rate (0.0 to 1.0) */
1351→+  errorRateMax: number;
1352→+}
1353→+
1354→+export interface ThresholdResult {
1355→+  passed: boolean;
1356→+  violations: string[];
1357→+}
1358→+
1359→+/**
1360→+ * Check collected metrics against defined thresholds.
1361→+ * Returns pass/fail with descriptive violation messages.
1362→+ *
1363→+ * Operations in thresholds that are not found in metrics are silently
1364→+ * skipped — a scenario may not exercise every operation.
1365→+ */
1366→+export function checkThresholds(
1367→+  metrics: OperationMetrics[],
1368→+  thresholds: ThresholdConfig[]
1369→+): ThresholdResult {
1370→+  const violations: string[] = [];
1371→+
1372→+  for (const t of thresholds) {
1373→+    const m = metrics.find((op) => op.operation === t.operation);
1374→+    if (!m) continue;
1375→+
1376→+    if (m.latency.p95 > t.p95MaxMs) {
1377→+      violations.push(
1378→+        `${t.operation} p95 ${Math.round(m.latency.p95)}ms exceeds threshold ${t.p95MaxMs}ms`
1379→+      );
1380→+    }
1381→+
1382→+    const errorRate = m.count > 0 ? m.errors / m.count : 0;
1383→+    if (errorRate > t.errorRateMax) {
1384→+      violations.push(
1385→+        `${t.operation} error rate ${(errorRate * 100).toFixed(1)}% exceeds threshold ${(t.errorRateMax * 100).toFixed(1)}%`
1386→+      );
1387→+    }
1388→+  }
1389→+
1390→+  return { passed: violations.length === 0, violations };
1391→+}
