 17→
 18→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
 19→const DURATION_SEC = parseInt(process.env.LOAD_TEST_DURATION ?? '300', 10);
 20→const OPS_PER_SEC_PER_CLIENT = 2;
 21→
 22→describe('Sustained Load', () => {
 23→  let pool: PoolClient[] = [];
 24→
 25→  afterAll(async () => {
 26→    await destroyClientPool(pool);
 27→  });
 28→
 29→  it(`${NUM_CLIENTS} clients × ${OPS_PER_SEC_PER_CLIENT} ops/sec for ${DURATION_SEC}s`, async () => {
 30→    pool = await createClientPool({
 31→      clientCount: NUM_CLIENTS,
 32→      label: 'sustained',
 33→    });
 34→
 35→    const endTime = Date.now() + DURATION_SEC * 1000;
 36→
 37→    const results = await Promise.allSettled(
 38→      pool.map((pc) => runSustainedClient(pc, endTime, OPS_PER_SEC_PER_CLIENT))
 39→    );
 40→
 41→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
 42→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
 43→
 44→    const metrics = await aggregateAndReport('Sustained Load', pool);
 45→
 46→    // Threshold check: same as upload-throughput for sustained operations
 47→    const THRESHOLDS: ThresholdConfig[] = [
 48→      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
 49→      { operation: 'createFolder', p95MaxMs: 5_000, errorRateMax: 0.05 },
 50→    ];
 51→
 52→    const thresholdResult = checkThresholds(metrics, THRESHOLDS);
 53→    if (!thresholdResult.passed) {
 54→      console.warn('THRESHOLD VIOLATIONS:');
 55→      thresholdResult.violations.forEach((v) => console.warn(`  - ${v}`));
 56→    }
 57→    expect(
 58→      thresholdResult.passed,
 59→      `Threshold violations:\n${thresholdResult.violations.join('\n')}`
 60→    ).toBe(true);
 61→  });
 62→});
 63→
 64→async function runSustainedClient(
 65→  pc: PoolClient,
 66→  endTime: number,
 67→  opsPerSec: number
 68→): Promise<void> {
 69→  const { client, rootIpnsName, metrics } = pc;
 70→  metrics.start();
 71→
 72→  const intervalMs = 1000 / opsPerSec;
 73→  let folderCounter = 0;
 74→
 75→  while (Date.now() < endTime) {
 76→    const opStart = Date.now();
 77→
 78→    try {
 79→      // Alternate between folder create and delete to keep state manageable
 80→      const name = `sustained-${pc.id}-${folderCounter++}`;
 81→
 82→      const folder = await metrics.measure('createFolder', () =>
 83→        client.createFolder(rootIpnsName, name)
 84→      );
 85→
 86→      // Small file upload
 87→      const data = new Uint8Array(1024);
 88→      crypto.getRandomValues(data);
 89→      await metrics.measure(
 90→        'uploadFile',
 91→        () => client.uploadFile(rootIpnsName, data, `${name}.bin`, 'application/octet-stream'),
 92→        1024
 93→      );
 94→
 95→      // Cleanup to prevent state bloat
 96→      const folderState = client.getFolderTree().get(rootIpnsName);
 97→      const fileChild = folderState?.children.find((c) => c.name === `${name}.bin`);
 98→      if (fileChild) {
 99→        await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, fileChild.id));
100→      }
101→      await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
102→    } catch {
103→      // Non-fatal — continue the sustained load
104→    }
105→
106→    // Wait for next interval
107→    const elapsed = Date.now() - opStart;
108→    const wait = Math.max(0, intervalMs - elapsed);
109→    if (wait > 0) {
110→      await new Promise((r) => setTimeout(r, wait));
111→    }
112→  }
113→
114→  metrics.stop();
115→}
