 1→/**
 2→ * Spike Test Scenario
 3→ *
 4→ * Starts with a baseline of 2 clients, then bursts to 20 clients.
 5→ * Measures recovery time — how long until latencies return to baseline.
 6→ */
 7→
 8→import { describe, it, afterAll, expect } from 'vitest';
 9→import {
10→  createClientPool,
11→  destroyClientPool,
12→  aggregateAndReport,
13→  type PoolClient,
14→} from '../harness/client-pool';
15→import { checkThresholds, type ThresholdConfig } from '../harness/thresholds';
16→import { runFolderWorkload } from '../workloads/folder-workload';
17→
18→const BASELINE_CLIENTS = 2;
19→const BURST_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
20→const BASELINE_CYCLES = 10;
21→const BURST_CYCLES = 30;
22→
23→describe('Spike Test', () => {
24→  let baselinePool: PoolClient[] = [];
25→  let burstPool: PoolClient[] = [];
26→
27→  afterAll(async () => {
28→    await destroyClientPool(baselinePool);
29→    await destroyClientPool(burstPool);
30→  });
31→
32→  it(`baseline ${BASELINE_CLIENTS} clients → burst ${BURST_CLIENTS} clients`, async () => {
33→    // Phase 1: Baseline
34→    console.log('\n--- Phase 1: Baseline ---');
35→    baselinePool = await createClientPool({
36→      clientCount: BASELINE_CLIENTS,
37→      label: 'spike-baseline',
38→    });
39→
40→    await Promise.allSettled(
41→      baselinePool.map((pc) => {
42→        pc.metrics.start();
43→        return runFolderWorkload(pc, { cycles: BASELINE_CYCLES }).finally(() => pc.metrics.stop());
44→      })
45→    );
46→
47→    const baselineMetrics = await aggregateAndReport('Spike Test - Baseline', baselinePool);
48→
49→    // Phase 2: Burst
50→    console.log('\n--- Phase 2: Burst ---');
51→    burstPool = await createClientPool({
52→      clientCount: BURST_CLIENTS,
53→      label: 'spike-burst',
54→    });
55→
56→    await Promise.allSettled(
57→      burstPool.map((pc) => {
58→        pc.metrics.start();
59→        return runFolderWorkload(pc, { cycles: BURST_CYCLES }).finally(() => pc.metrics.stop());
60→      })
61→    );
62→
63→    const burstMetrics = await aggregateAndReport('Spike Test - Burst', burstPool);
64→
65→    // Compare baseline vs burst latencies
66→    console.log('\n--- Latency Comparison (p95) ---');
67→    for (const baseOp of baselineMetrics) {
68→      const burstOp = burstMetrics.find((b) => b.operation === baseOp.operation);
69→      if (burstOp) {
70→        const degradation = (
71→          ((burstOp.latency.p95 - baseOp.latency.p95) / baseOp.latency.p95) *
72→          100
73→        ).toFixed(0);
74→        console.log(
75→          `  ${baseOp.operation}: baseline=${Math.round(baseOp.latency.p95)}ms → burst=${Math.round(burstOp.latency.p95)}ms (${degradation}% change)`
76→        );
77→      }
78→    }
79→
80→    // Threshold check on burst phase: generous limits for intentional overload
81→    const THRESHOLDS: ThresholdConfig[] = [
82→      { operation: 'uploadFile', p95MaxMs: 15_000, errorRateMax: 0.15 },
83→      { operation: 'createFolder', p95MaxMs: 15_000, errorRateMax: 0.15 },
84→    ];
85→
86→    const thresholdResult = checkThresholds(burstMetrics, THRESHOLDS);
87→    if (!thresholdResult.passed) {
88→      console.warn('THRESHOLD VIOLATIONS:');
89→      thresholdResult.violations.forEach((v) => console.warn(`  - ${v}`));
90→    }
91→    expect(
92→      thresholdResult.passed,
93→      `Threshold violations:\n${thresholdResult.violations.join('\n')}`
94→    ).toBe(true);
95→  });
96→});
