 86→/**
 87→ * Create a new subfolder with generated keys.
 88→ *
 89→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 90→ * wraps them with the user's public key for storage.
 91→ *
 92→ * @returns Created folder entry and decrypted keys
 93→ */
 94→export async function createSubfolder(params: {
 95→  name: string;
 96→  userPublicKey: Uint8Array;
 97→  teeKeys?: TeeKeys;
 98→}): Promise<{
 99→  folder: FolderEntry;
100→  ipnsPrivateKey: Uint8Array;

 60→ * @param params.userPublicKey - User's secp256k1 public key for ECIES wrapping
 61→ * @param params.ctx - SDK context for API access
 62→ * @param params.onProgress - Optional upload progress callback
 63→ * @param params.teeKeys - Optional TEE keys for IPNS private key enrollment
 64→ */
 65→export async function uploadFile(params: {
 66→  data: Uint8Array;
 67→  fileId: string;
 68→  mimeType: string;
 69→  folderKey: Uint8Array;
 70→  userPublicKey: Uint8Array;
 71→  ctx: SdkContext;
 72→  onProgress?: ProgressCallback;
 73→  teeKeys?: TeeKeys;
 74→}): Promise<UploadResult> {
 75→  return withPerf('upload:full', async () => {
 76→    // 1. Generate unique file key and IV
 77→    const fileKey = generateFileKey();
 78→    const iv = generateIv();
 79→
 80→    try {
 81→      // 2. Encrypt with AES-256-GCM
 82→      const ciphertext = await encryptAesGcm(params.data, fileKey, iv);
 83→
 84→      // 3. Wrap file key with user's public key (ECIES)
 85→      const wrappedKey = await wrapKey(fileKey, params.userPublicKey);
 86→
 87→      // 4. Upload encrypted content to IPFS
 88→      const { cid, size: encryptedSize } = await addToIpfs(
 89→        params.ctx,
 90→        ciphertext,
 91→        params.onProgress
 92→      );
 93→
 94→      // 5. Create per-file IPNS metadata record
 95→      const fileMetaResult = await createFileMetadata({
 96→        fileId: params.fileId,
 97→        cid,
 98→        fileKeyEncrypted: bytesToHex(wrappedKey),
 99→        fileIv: bytesToHex(iv),
100→        size: params.data.length,
101→        mimeType: params.mimeType,
102→        folderKey: params.folderKey,
103→        userPublicKey: params.userPublicKey,
104→        ctx: params.ctx,
105→        teeKeys: params.teeKeys,
106→        encryptionMode: 'GCM',
107→      });
108→
109→      // Return a defensive copy of the file key for re-wrapping.
110→      // The caller is responsible for clearing it after use.
111→      const fileKeyCopy = new Uint8Array(fileKey);
112→
113→      return {
114→        cid,
115→        encryptedSize,
116→        fileMetaIpnsName: fileMetaResult.fileMetaIpnsName,
117→        ipnsRecord: fileMetaResult.ipnsRecord,
118→        ipnsPrivateKeyEncrypted: fileMetaResult.ipnsPrivateKeyEncrypted,
119→        fileKey: fileKeyCopy,
120→      };
121→    } finally {
122→      // 6. Clear the internal copy of the key from memory
123→      clearBytes(fileKey);
124→    }
125→  });
126→}
