 10→/**
 11→ * Upload encrypted data to IPFS via backend relay.
 12→ * Uses ctx.axiosInstance when available (gets auth interceptors + default headers),
 13→ * falls back to bare axios with manual token injection.
 14→ */
 15→export async function addToIpfs(
 16→  ctx: SdkContext,
 17→  encryptedData: Uint8Array,
 18→  onProgress?: ProgressCallback,
 19→  cancelToken?: CancelToken
 20→): Promise<IpfsAddResult> {
 21→  return withPerf('ipfs:upload', async () => {
 22→    const blob = new Blob([encryptedData as BlobPart]);
 23→    const formData = new FormData();
 24→    formData.append('file', blob);
 25→
 26→    const requestConfig = {
 27→      onUploadProgress: (event: AxiosProgressEvent) => {
 28→        if (event.total && onProgress) {
 29→          onProgress(Math.round((event.loaded * 100) / event.total));
 30→        }
 31→      },
 32→      cancelToken,
 33→    };
 34→
 35→    if (ctx.axiosInstance) {
