 56→ */
 57→export async function unpinFromIpfs(ctx: SdkContext, cid: string): Promise<void> {
 58→  if (ctx.axiosInstance) {
 59→    await ctx.axiosInstance.post('/ipfs/unpin', { cid });
 60→    return;
 61→  }
 62→
 63→  const token = await ctx.getAccessToken();
 64→  await axios.post(
