 71→/**
 72→ * Fetch encrypted data from IPFS via backend relay.
 73→ * Uses native fetch for streaming download progress support.
 74→ * Auth token is obtained from ctx (axiosInstance interceptor isn't used
 75→ * here because fetch provides ReadableStream for progress tracking).
 76→ */
 77→export async function fetchFromIpfs(
 78→  ctx: SdkContext,
 79→  cid: string,
 80→  onProgress?: DownloadProgressCallback
 81→): Promise<Uint8Array> {
 82→  return withPerf('ipfs:download', async () => {
 83→    const token = await ctx.getAccessToken();
 84→    const response = await fetch(`${ctx.apiUrl}/ipfs/${cid}`, {
 85→      headers: { Authorization: `Bearer ${token}` },
 86→    });
 87→    if (!response.ok) throw new Error(`Failed to fetch from IPFS: ${response.status}`);
 88→
 89→    const contentLength = response.headers.get('Content-Length');
 90→    if (!onProgress || !contentLength) {
 91→      return new Uint8Array(await response.arrayBuffer());
 92→    }
 93→
 94→    const total = parseInt(contentLength, 10);
 95→    const reader = response.body?.getReader();
 96→    if (!reader) throw new Error('ReadableStream not supported');
 97→
 98→    const chunks: Uint8Array[] = [];
 99→    let loaded = 0;
100→    while (true) {
101→      const { done, value } = await reader.read();
102→      if (done) break;
103→      chunks.push(value);
104→      loaded += value.length;
105→      onProgress(loaded, total);
106→    }
107→
108→    const result = new Uint8Array(loaded);
109→    let offset = 0;
110→    for (const chunk of chunks) {
111→      result.set(chunk, offset);
112→      offset += chunk.length;
113→    }
114→    return result;
115→  });
116→}
