/**
 * Upload Throughput Scenario
 *
 * N clients each upload M files (1KB-500KB), measuring upload pipeline
 * throughput including IPNS publish per file.
 */

import { describe, it, afterAll, expect } from 'vitest';
import {
  createClientPool,
  destroyClientPool,
  aggregateAndReport,
  type PoolClient,
} from '../harness/client-pool';
import { expectThresholdsPassed, type ThresholdConfig } from '../harness/thresholds';
import { runFileWorkload } from '../workloads/file-workload';

const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '10', 10);
const FILES_PER_CLIENT = 20;

describe('Upload Throughput', () => {
  let pool: PoolClient[] = [];

  afterAll(async () => {
    await destroyClientPool(pool);
  });

  it(`${NUM_CLIENTS} clients × ${FILES_PER_CLIENT} files (1KB-500KB)`, async () => {
    pool = await createClientPool({
      clientCount: NUM_CLIENTS,
      label: 'upload-throughput',
    });

    const results = await Promise.allSettled(
      pool.map((pc) => {
        pc.metrics.start();
        return runFileWorkload(pc, {
          fileCount: FILES_PER_CLIENT,
          minSize: 1_024,
          maxSize: 500 * 1_024,
          verifyDownloads: false,
        }).finally(() => pc.metrics.stop());
      })
    );

    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
    const failed = results.filter((r) => r.status === 'rejected').length;
    console.log(`\nClients completed: ${succeeded} succeeded, ${failed} failed`);

    const metrics = await aggregateAndReport('Upload Throughput', pool);

    // Threshold check: 2-3x observed baselines from Phase 19.2
    const THRESHOLDS: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
    ];

    expectThresholdsPassed(metrics, THRESHOLDS);
  });
});

/**
 * Mixed Workload Scenario
 *
 * Simulates realistic usage: folder CRUD, file uploads, renames, moves, deletes
 * with weighted probabilities. Tests the system under representative load.
 */

import { describe, it, afterAll, expect } from 'vitest';
import {
  createClientPool,
  destroyClientPool,
  aggregateAndReport,
  type PoolClient,
} from '../harness/client-pool';
import { expectThresholdsPassed, type ThresholdConfig } from '../harness/thresholds';
import { runMixedWorkload } from '../workloads/mixed-workload';

const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
const OPS_PER_CLIENT = 45;

describe('Mixed Workload', () => {
  let pool: PoolClient[] = [];

  afterAll(async () => {
    await destroyClientPool(pool);
  });

  it(`${NUM_CLIENTS} clients × ${OPS_PER_CLIENT} mixed ops`, async () => {
    pool = await createClientPool({
      clientCount: NUM_CLIENTS,
      label: 'mixed',
    });

    const results = await Promise.allSettled(
      pool.map((pc) => {
        pc.metrics.start();
        return runMixedWorkload(pc, {
          totalOps: OPS_PER_CLIENT,
          weights: {
            createFolder: 2,
            uploadFile: 4,
            renameItem: 1,
            moveItem: 1,
            deleteItem: 1,
          },
        }).finally(() => pc.metrics.stop());
      })
    );

    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
    console.log(`\nClients completed: ${succeeded}/${pool.length}`);

    const metrics = await aggregateAndReport('Mixed Workload', pool);

    // Threshold check: generous limits for mixed workload (higher error rate historically)
    const THRESHOLDS: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.1 },
      { operation: 'createFolder', p95MaxMs: 5_000, errorRateMax: 0.1 },
    ];

    expectThresholdsPassed(metrics, THRESHOLDS);
  });
});

/**
 * IPNS Publish Storm Scenario
 *
 * N clients performing rapid folder mutations, each triggering IPNS publish.
 * Tests IPNS publish contention — the known system bottleneck.
 */

import { describe, it, afterAll, expect } from 'vitest';
import {
  createClientPool,
  destroyClientPool,
  aggregateAndReport,
  type PoolClient,
} from '../harness/client-pool';
import { expectThresholdsPassed, type ThresholdConfig } from '../harness/thresholds';
import { runFolderWorkload } from '../workloads/folder-workload';

const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
const CYCLES_PER_CLIENT = 50;

describe('IPNS Publish Storm', () => {
  let pool: PoolClient[] = [];

  afterAll(async () => {
    await destroyClientPool(pool);
  });

  it(`${NUM_CLIENTS} clients × ${CYCLES_PER_CLIENT} folder create-rename-delete cycles`, async () => {
    pool = await createClientPool({
      clientCount: NUM_CLIENTS,
      label: 'ipns-storm',
    });

    const results = await Promise.allSettled(
      pool.map((pc) => {
        pc.metrics.start();
        return runFolderWorkload(pc, { cycles: CYCLES_PER_CLIENT }).finally(() =>
          pc.metrics.stop()
        );
      })
    );

    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
    console.log(`\nClients completed: ${succeeded}/${pool.length}`);

    const metrics = await aggregateAndReport('IPNS Publish Storm', pool);

    // Threshold check: IPNS contention scenario, high variance expected
    const THRESHOLDS: ThresholdConfig[] = [
      { operation: 'createFolder', p95MaxMs: 10_000, errorRateMax: 0.1 },
    ];

    expectThresholdsPassed(metrics, THRESHOLDS);
  });
});

/**
 * Sustained Load Scenario
 *
 * N clients running at a steady rate for a configurable duration.
 * Tests latency stability over time — detects memory leaks, connection
 * pool exhaustion, and other time-dependent degradation.
 */

import { describe, it, afterAll, expect } from 'vitest';
import {
  createClientPool,
  destroyClientPool,
  aggregateAndReport,
  type PoolClient,
} from '../harness/client-pool';
import { expectThresholdsPassed, type ThresholdConfig } from '../harness/thresholds';

const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
const DURATION_SEC = parseInt(process.env.LOAD_TEST_DURATION ?? '300', 10);
const OPS_PER_SEC_PER_CLIENT = 2;

describe('Sustained Load', () => {
  let pool: PoolClient[] = [];

  afterAll(async () => {
    await destroyClientPool(pool);
  });

  it(`${NUM_CLIENTS} clients × ${OPS_PER_SEC_PER_CLIENT} ops/sec for ${DURATION_SEC}s`, async () => {
    pool = await createClientPool({
      clientCount: NUM_CLIENTS,
      label: 'sustained',
    });

    const endTime = Date.now() + DURATION_SEC * 1000;

    const results = await Promise.allSettled(
      pool.map((pc) => runSustainedClient(pc, endTime, OPS_PER_SEC_PER_CLIENT))
    );

    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
    console.log(`\nClients completed: ${succeeded}/${pool.length}`);

    const metrics = await aggregateAndReport('Sustained Load', pool);

    // Threshold check: same as upload-throughput for sustained operations
    const THRESHOLDS: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 10_000, errorRateMax: 0.05 },
      { operation: 'createFolder', p95MaxMs: 5_000, errorRateMax: 0.05 },
    ];

    expectThresholdsPassed(metrics, THRESHOLDS);
  });
});

async function runSustainedClient(
  pc: PoolClient,
  endTime: number,
  opsPerSec: number
): Promise<void> {
  const { client, rootIpnsName, metrics } = pc;
  metrics.start();

  const intervalMs = 1000 / opsPerSec;
  let folderCounter = 0;

  while (Date.now() < endTime) {
    const opStart = Date.now();

    try {
      // Alternate between folder create and delete to keep state manageable
      const name = `sustained-${pc.id}-${folderCounter++}`;

      const folder = await metrics.measure('createFolder', () =>
        client.createFolder(rootIpnsName, name)
      );

      // Small file upload
      const data = new Uint8Array(1024);
      crypto.getRandomValues(data);
      await metrics.measure(
        'uploadFile',
        () => client.uploadFile(rootIpnsName, data, `${name}.bin`, 'application/octet-stream'),
        1024
      );

      // Cleanup to prevent state bloat
      const folderState = client.getFolderTree().get(rootIpnsName);
      const fileChild = folderState?.children.find((c) => c.name === `${name}.bin`);
      if (fileChild) {
        await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, fileChild.id));
      }
      await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
    } catch {
      // Non-fatal — continue the sustained load
    }

    // Wait for next interval
    const elapsed = Date.now() - opStart;
    const wait = Math.max(0, intervalMs - elapsed);
    if (wait > 0) {
      await new Promise((r) => setTimeout(r, wait));
    }
  }

  metrics.stop();
}

/**
 * Spike Test Scenario
 *
 * Starts with a baseline of 2 clients, then bursts to 20 clients.
 * Measures recovery time — how long until latencies return to baseline.
 */

import { describe, it, afterAll, expect } from 'vitest';
import {
  createClientPool,
  destroyClientPool,
  aggregateAndReport,
  type PoolClient,
} from '../harness/client-pool';
import { expectThresholdsPassed, type ThresholdConfig } from '../harness/thresholds';
import { runFolderWorkload } from '../workloads/folder-workload';

const BASELINE_CLIENTS = 2;
const BURST_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
const BASELINE_CYCLES = 10;
const BURST_CYCLES = 30;

describe('Spike Test', () => {
  let baselinePool: PoolClient[] = [];
  let burstPool: PoolClient[] = [];

  afterAll(async () => {
    await destroyClientPool(baselinePool);
    await destroyClientPool(burstPool);
  });

  it(`baseline ${BASELINE_CLIENTS} clients → burst ${BURST_CLIENTS} clients`, async () => {
    // Phase 1: Baseline
    console.log('\n--- Phase 1: Baseline ---');
    baselinePool = await createClientPool({
      clientCount: BASELINE_CLIENTS,
      label: 'spike-baseline',
    });

    await Promise.allSettled(
      baselinePool.map((pc) => {
        pc.metrics.start();
        return runFolderWorkload(pc, { cycles: BASELINE_CYCLES }).finally(() => pc.metrics.stop());
      })
    );

    const baselineMetrics = await aggregateAndReport('Spike Test - Baseline', baselinePool);

    // Phase 2: Burst
    console.log('\n--- Phase 2: Burst ---');
    burstPool = await createClientPool({
      clientCount: BURST_CLIENTS,
      label: 'spike-burst',
    });

    await Promise.allSettled(
      burstPool.map((pc) => {
        pc.metrics.start();
        return runFolderWorkload(pc, { cycles: BURST_CYCLES }).finally(() => pc.metrics.stop());
      })
    );

    const burstMetrics = await aggregateAndReport('Spike Test - Burst', burstPool);

    // Compare baseline vs burst latencies
    console.log('\n--- Latency Comparison (p95) ---');
    for (const baseOp of baselineMetrics) {
      const burstOp = burstMetrics.find((b) => b.operation === baseOp.operation);
      if (burstOp) {
        const degradation = (
          ((burstOp.latency.p95 - baseOp.latency.p95) / baseOp.latency.p95) *
          100
        ).toFixed(0);
        console.log(
          `  ${baseOp.operation}: baseline=${Math.round(baseOp.latency.p95)}ms → burst=${Math.round(burstOp.latency.p95)}ms (${degradation}% change)`
        );
      }
    }

    // Threshold check on burst phase: generous limits for intentional overload
    const THRESHOLDS: ThresholdConfig[] = [
      { operation: 'uploadFile', p95MaxMs: 15_000, errorRateMax: 0.15 },
      { operation: 'createFolder', p95MaxMs: 15_000, errorRateMax: 0.15 },
    ];

    expectThresholdsPassed(burstMetrics, THRESHOLDS);
  });
});

